import{z as s,x as i,o as B,c as d,q as o,j as n,D as a,d as A,s as t,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"视频理解的服务","description":"","frontmatter":{"title":"视频理解的服务","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mm-video-serving.md","filePath":"llm/mm-video-serving.md","lastUpdated":1791413859000}'),m={name:"llm/mm-video-serving.md"};function p(D,E,C,h,f,F){const l=i("Mermaid");return B(),d("div",null,[E[2]||(E[2]=o('<h1 id="视频理解的服务" tabindex="-1">视频理解的服务 <a class="header-anchor" href="#视频理解的服务" aria-label="Permalink to &quot;视频理解的服务&quot;">​</a></h1><div class="epigraph"><p>视频服务的难点不在每帧更贵，而在时间维把预算变成流：你没法等一部电影编码完，再回答关于开头的问题。</p><footer>—— 据 Qwen2.5-VL Technical Report 的动态 FPS 与时间 MRoPE 叙述、视频 token 文献整理</footer></div><p><a href="/llm/mm-visual-token-budget">上一课</a>把单图 token 预算立成三层闸；视频把预算乘上时间维——帧数乘每帧 token，一分钟素材顶上百张图。主干课已写抽帧与时间位置（<a href="/llm/video-tokens">视频 token</a>）与抽帧后的时序融合（<a href="/llm/video-temporal-pool">时间池化</a>）。缺口是服务语义：离线与流式是两种负载，帧缓存怎么键、容量按什么规划、采样率改变时模型怎么知道。本课只写服务侧，抽帧与位置编码只引用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>先把账摆出来：抽 2 fps、每帧按单图预算，一分钟素材顶上百张图、越过大半个上下文窗口（细账见下方注）。降量有两个旋钮——抽帧率与每帧预算——但二者不独立定价：降抽帧率丢时间分辨率，压每帧预算丢空间分辨率，问答类型决定哪个先让。时间语义是第二重约束：模型靠<a href="/llm/qwen25-vl">绝对时间对齐的 MRoPE</a> 知道两帧之间过了 0.5 秒还是 5 秒，服务侧任何抽帧、丢帧、变速都必须把真实时间戳传给预处理，否则模型看到的只是「第几张图」的均匀序列，运动速度的几何整体错掉。</p><p><span class="marginnote">「MRoPE」可拆开看：RoPE 是旋转位置编码——给每个 token 发一个「位置坐标」，注意力靠坐标远近判断谁和谁相关；MRoPE 把坐标从一维扩成多维，时间、高度、宽度各占一维，模型才知道「第 37 秒、画面上方」这种位置。</span></p><p>服务形态因此分叉。<strong>离线</strong>：素材已在，转码式批量抽帧、批量编码、一次性进上下文，追求总时长与成本。<strong>流式</strong>：边录边看边答（监控、会议、直播），新帧持续到达，答案只基于已见前缀，追求「事件到可问」的延迟。两种形态共享编码器池，但队列行为完全不同：前者是大批离线任务，后者是按会话常驻的增量流。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离线管线把上一课的三层预算接上时间维：场景检测切镜头，镜头内按设定 fps 抽帧，逐帧走<a href="/llm/mm-visual-token-budget">图级预算</a>缩放，再按时间池化合并相邻帧；预算闸从「每图」升级为「每分钟素材」定额。批处理用足<a href="/llm/mm-serving-vision-encoder">编码器池</a>的优势——同视频帧形状一致，桶内方差近乎零。</p><p>流式管线的核心是<strong>增量上下文</strong>：滑动窗口内的帧编码后常驻 KV，新帧只编码增量，窗口左沿的旧帧按策略驱逐或摘要；问答请求拼在当前前缀上即时 prefill。跨请求复用靠帧级缓存：键是「视频内容 hash + 时间区间 + 采样参数」，同一素材被多人观看时编码只发生一次——这是<a href="/llm/mm-serving-vision-encoder">嵌入缓存</a>从图到帧的推广，收益随点播集中度放大。</p><p><span class="marginnote">增量上下文可以类比看直播记笔记：不必每来一帧就把全场重看一遍，只把新画面补进笔记本，太老的页撕掉（驱逐）或浓缩成摘要。观众随时提问，你翻的永远是当前笔记本，而不是从第一帧重来。</span></p><p><span class="marginnote">同样一分钟，2 fps、每帧 256 token 约 3 万 token，是单图 1536 预算的二十倍。视频服务的定价与配额单位应是「每分钟素材」，把「每次请求」的直觉直接搬过来会系统性低估一个量级。</span></p>',12)),(B(),n(r,null,{default:a(()=>[t(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E8%A7%86%E9%A2%91%E6%BA%90%22%5D%20--%3E%20DET%7B%22%E6%9C%8D%E5%8A%A1%E5%BD%A2%E6%80%81%22%7D%0A%20%20DET%20--%3E%7C%E7%A6%BB%E7%BA%BF%7C%20SCENE%5B%22%E5%9C%BA%E6%99%AF%E6%A3%80%E6%B5%8B%E5%88%87%E9%95%9C%E5%A4%B4%22%5D%0A%20%20DET%20--%3E%7C%E6%B5%81%E5%BC%8F%7C%20WIN%5B%22%E6%BB%91%E5%8A%A8%E7%AA%97%E5%8F%A3%E6%8E%A5%E6%96%B0%E5%B8%A7%22%5D%0A%20%20SCENE%20--%3E%20FPS%5B%22%E6%8C%89%20fps%20%E6%8A%BD%E5%B8%A7%22%5D%0A%20%20FPS%20--%3E%20BUD%5B%22%E9%80%90%E5%B8%A7%E9%A2%84%E7%AE%97%E7%BC%A9%E6%94%BE%22%5D%0A%20%20BUD%20--%3E%20POOL%5B%22%E6%97%B6%E9%97%B4%E6%B1%A0%E5%8C%96%E5%90%88%E5%B9%B6%22%5D%0A%20%20WIN%20--%3E%20BUD%0A%20%20POOL%20--%3E%20ENC%5B%22%E6%89%B9%E9%87%8F%E7%BC%96%E7%A0%81%22%5D%0A%20%20BUD%20--%3E%20SENC%5B%22%E5%A2%9E%E9%87%8F%E7%BC%96%E7%A0%81%E5%85%A5%E5%B8%B8%E9%A9%BB%20KV%22%5D%0A%20%20ENC%20--%3E%20TS%5B%22%E6%90%BA%E5%B8%A6%E7%BB%9D%E5%AF%B9%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A%20%20SENC%20--%3E%20TS%0A%20%20TS%20--%3E%20QA%5B%22%E9%97%AE%E7%AD%94%E5%89%8D%E7%BC%80%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"时间戳因此是隐藏合同：变速转码、丢帧容错、直播卡顿都会让「帧序号」与「真实时间」脱钩，预处理必须携带秒级元数据；评测也要放时间定位题来盯——丢时间戳的服务在「第 37 秒发生了什么」类问题上会安静地答错。",-1)),E[5]||(E[5]=e("p",null,"容量规划按流式走：编码器池要扛的是稳态帧率总和（每路 fps 乘并发会话数），不是请求数；窗口长度乘每帧 token 给出单会话 KV 常驻量，决定单卡能同时养几路流。离线批相反，用大批换吞吐，两类负载不应混队——混队会让流式的「事件到可问」延迟被离线大批顶穿。",-1)),(B(),n(r,null,{default:a(()=>[t(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%7B%22%E5%8D%95%E5%8D%A1%E8%83%BD%E5%90%8C%E6%97%B6%E5%85%BB%E5%87%A0%E8%B7%AF%E6%B5%81%3F%22%7D%20--%3E%20A%5B%22%E7%AE%97%E5%8D%95%E4%BC%9A%E8%AF%9D%20KV%20%E5%B8%B8%E9%A9%BB%22%5D%0A%20%20A%20--%3E%20CALC%5B%22%E7%AA%97%E5%8F%A3%E5%B8%A7%E6%95%B0%20%C3%97%20%E6%AF%8F%E5%B8%A7%20token%22%5D%0A%20%20CALC%20--%3E%20EX%5B%22%E4%BE%8B%EF%BC%9A60%20%E5%B8%A7%20%C3%97%20256%20token%20%3D%2015360%20token%20KV%22%5D%0A%20%20EX%20--%3E%20DIV%5B%22%E5%8F%AF%E7%94%A8%20KV%20%C3%B7%20%E5%8D%95%E4%BC%9A%E8%AF%9D%20%3D%20KV%20%E8%B7%AF%E6%95%B0%E4%B8%8A%E9%99%90%22%5D%0A%20%20F%20--%3E%20B%5B%22%E7%AE%97%E7%BC%96%E7%A0%81%E5%90%9E%E5%90%90%22%5D%0A%20%20B%20--%3E%20FPS%5B%22%E6%AF%8F%E8%B7%AF%20fps%20%C3%97%20%E5%B9%B6%E5%8F%91%20%3D%20%E7%A8%B3%E6%80%81%E5%B8%A7%E7%8E%87%E6%80%BB%E5%92%8C%22%5D%0A%20%20FPS%20--%3E%20CAP%5B%22%E7%BC%96%E7%A0%81%E6%B1%A0%E6%AF%8F%E7%A7%92%E4%BA%A7%E8%83%BD%E9%A1%BB%E5%A4%A7%E4%BA%8E%E7%AD%89%E4%BA%8E%E5%B8%A7%E7%8E%87%E6%80%BB%E5%92%8C%22%5D%0A%20%20DIV%20--%3E%20LIM%5B%22%E8%B7%AF%E6%95%B0%20%3D%20%E4%B8%A4%E4%B8%AA%E4%B8%8A%E9%99%90%E5%8F%96%E5%B0%8F%22%5D%0A%20%20CAP%20--%3E%20LIM%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>流式与完整性互斥：答案只对已见前缀负责，产品必须把「截至第几秒」暴露给用户，否则「没看见」会被当成「没答对」。<span class="marginnote">初学者容易把流式答案当「完整答案」用——其实它只对已见前缀负责。界面上不标「截至第几秒」，用户就会把「还没看到」当成「没答对」，这类问题在监控里表现为答案质量下降，实为预期行为。</span>抽帧间隙是另一类盲区：事件落在两帧之间，提高每帧分辨率救不了，只能加抽帧率或回放定位——这决定「先快答再精读」的两段式形态。点播缓存的隐私账要单算：内容 hash 键命中率越高，敏感素材的帧 KV 停留越久，淘汰策略要把会话结束当硬边界。长视频超出窗口后靠检索与记忆接力，见<a href="/llm/long-video-understanding">长视频理解</a>；本课的窗口服务只负责把窗口内做对。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>视频预算是帧数乘每帧 token，配额单位应为「每分钟素材」，比单图直觉高一个量级。</li><li>离线与流式是两种负载：大批换吞吐与增量窗口保延迟，不应混队。</li><li>时间戳是服务与模型间的正确性合同，抽帧变速都要把真实秒数传下去。</li><li>帧级缓存键为内容 hash 加时间区间与采样参数；点播复用收益大，隐私淘汰要硬边界。</li><li>容量按稳态帧率与单会话 KV 常驻量规划；抽帧间隙的盲区靠帧率或回放补救。</li><li>出处：据 Qwen2.5-VL Technical Report（arXiv:2502.13923）动态 FPS 口径、视频 token 与长视频理解文献整理。</li></ul>',4))])}const P=s(m,[["render",p]]);export{k as __pageData,P as default};
